-- ==========================================
-- SVKM CAMPUS FOOD ORDERING SYSTEM DATABASE
-- RDBMS SQL SCHEMA & DATA DUMP
-- Compatible with: MySQL / PostgreSQL / SQLite
-- ==========================================

DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS coupons;
DROP TABLE IF EXISTS food_items;
DROP TABLE IF EXISTS users;

-- 1. USERS TABLE
CREATE TABLE users (
    id INT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    password VARCHAR(100) NOT NULL,
    role VARCHAR(20) DEFAULT 'student',
    canteen VARCHAR(50) DEFAULT 'ground',
    food_pref VARCHAR(20) DEFAULT 'normal',
    svkm_coins INT DEFAULT 0,
    loyalty_count INT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


-- 2. FOOD ITEMS (MENU) TABLE
CREATE TABLE food_items (
    id INT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(150) NOT NULL,
    description TEXT,
    price DECIMAL(10,2) NOT NULL,
    category VARCHAR(50) NOT NULL,
    canteen_ids VARCHAR(100),
    is_jain BOOLEAN DEFAULT 0,
    state_cuisine VARCHAR(50),
    rating DECIMAL(2,1) DEFAULT 4.5,
    reviews_count INT DEFAULT 0,
    prep_time INT DEFAULT 10,
    stock_status VARCHAR(20) DEFAULT 'in_stock',
    image_url VARCHAR(255)
);


-- 3. COUPONS TABLE
CREATE TABLE coupons (
    id INT PRIMARY KEY AUTO_INCREMENT,
    code VARCHAR(30) UNIQUE NOT NULL,
    description VARCHAR(255),
    discount_percent INT DEFAULT 0,
    discount_flat DECIMAL(10,2) DEFAULT 0,
    max_discount DECIMAL(10,2) DEFAULT 0,
    min_order DECIMAL(10,2) DEFAULT 0,
    type VARCHAR(30) DEFAULT 'regular',
    is_active BOOLEAN DEFAULT 1,
    redemption_count INT DEFAULT 0
);


-- 4. ORDERS TABLE
CREATE TABLE orders (
    id BIGINT PRIMARY KEY,
    order_code VARCHAR(20) UNIQUE NOT NULL,
    user_id INT,
    user_name VARCHAR(100),
    canteen_id VARCHAR(50),
    canteen_name VARCHAR(100),
    status VARCHAR(30) DEFAULT 'Placed',
    subtotal DECIMAL(10,2),
    discount DECIMAL(10,2) DEFAULT 0,
    total DECIMAL(10,2) NOT NULL,
    payment_method VARCHAR(50),
    payment_status VARCHAR(20) DEFAULT 'PAID',
    fulfillment_type VARCHAR(30) DEFAULT 'pickup',
    delivery_location VARCHAR(100),
    pickup_otp VARCHAR(10),
    coins_earned INT DEFAULT 0,
    coins_redeemed INT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id)
);

